from statlib import *
c=cell
U='collection-presentation'
def pid(n,k): return f'stat11-s{n:03}-{k}'
def bars(title,sub,cats,series,ymin,ymax,ticks,ylabel='',xlabel='',keys=None,fills=None,W=520,H=300,stack=False,aria=''):
    L,R,Tp,B=70,(130 if keys else 20),50,50
    pw,ph=W-L-R,H-Tp-B
    Y=lambda v:Tp+ph*(1-(v-ymin)/(ymax-ymin))
    o=T(W/2-0+ (L-R)/2,18,title,13,'middle',600)
    if sub:o+=T(W/2+(L-R)/2,34,sub,11)
    o+=f'<rect x="{L}" y="{Tp}" width="{pw}" height="{ph}" fill="none" stroke="#333"/>'
    for t in ticks: o+=f'<line x1="{L}" y1="{Y(t):.1f}" x2="{L+pw}" y2="{Y(t):.1f}" stroke="#bbb"/>'+T(L-6,Y(t)+4,str(t),11,'end')
    n=len(cats);gw=pw/n
    for i,cn in enumerate(cats):
        cx=L+gw*(i+.5)
        if stack:
            base=0
            for j,sr in enumerate(series):
                v=sr[i];o+=f'<rect x="{cx-gw*.3:.1f}" y="{Y(base+v):.1f}" width="{gw*.6:.1f}" height="{Y(base)-Y(base+v):.1f}" fill="{fills[j]}" stroke="#222"/>';base+=v
        else:
            k=len(series);bw=gw*.7/k
            for j,sr in enumerate(series):
                v=sr[i];x0=cx-gw*.35+bw*j
                o+=f'<rect x="{x0:.1f}" y="{Y(v):.1f}" width="{bw:.1f}" height="{Y(ymin)-Y(v):.1f}" fill="{fills[j]}" stroke="#222"/>'
        o+=T(cx,Tp+ph+16,cn,11)
    if xlabel:o+=T(L+pw/2,H-8,xlabel,12)
    if ylabel:o+=f'<text transform="translate(14 {Tp+ph/2}) rotate(-90)" font-size="11" text-anchor="middle" font-family="Arial">{ylabel}</text>'
    if keys:
        o+=T(L+pw+20,Tp+60,'Key',12,'start')
        for j,kn in enumerate(keys): o+=f'<rect x="{L+pw+20}" y="{Tp+75+j*20}" width="12" height="12" fill="{fills[j]}" stroke="#222"/>'+T(L+pw+38,Tp+86+j*20,kn,11,'start')
    return svg(W,H,aria,o)
